{
  "findings": [
    {
      "check_id": "CKV2_AWS_73",
      "title": "SQS Queue uses AWS-managed SSE instead of Customer-Managed Key (CMK)",
      "resource": "aws_sqs_queue.pass2",
      "severity": "MEDIUM",
      "explanation": "The queue is configured with `sqs_managed_sse_enabled = true`, which uses an AWS-managed key. Security best practices and the retrieved knowledge base recommend using a Customer-Managed Key (CMK) via KMS for better control over encryption keys, rotation, and access policies."
    }
  ],
  "patched_code": "resource \"aws_kms_key\" \"sqs_key\" {\n  description             = \"KMS key for SQS queue encryption\"\n  deletion_window_in_days = 10\n  enable_key_rotation     = true\n}\n\nresource \"aws_sqs_queue\" \"pass2\" {\n  name                      = \"unencrypted-queue\"\n  kms_master_key_id         = aws_kms_key.sqs_key.id\n  sqs_managed_sse_enabled   = false\n}",
  "fix_summary": "Added an AWS KMS key resource to serve as a Customer-Managed Key (CMK). Updated the SQS queue to use this KMS key (`kms_master_key_id`) and disabled `sqs_managed_sse_enabled` to comply with CKV2_AWS_73."
}
